from lib import *
S = SS('f117')
R = J('f117'); sc = R['scale']; se = R['ser']; gz = R['gz']; lv = R['live']; to = R['timeout']
a, b, c_ = sc['1000'], sc['10000'], sc['100000']
steps = [
    step(f"jsonify 一个大列表(每行 6 个字段):1000 行 {a[0]:.1f} ms、响应 {a[1] / 1e6:.2f} MB、峰值内存 {a[2] / 1e6:.1f} MB;1 万行 {b[0]:.1f} ms、{b[1] / 1e6:.2f} MB、{b[2] / 1e6:.1f} MB;10 万行 {c_[0]:.1f} ms、{c_[1] / 1e6:.2f} MB、{c_[2] / 1e6:.1f} MB。耗时与内存都随行数线性增长,峰值内存约是响应体积的两倍(列表序列化成字符串再编码成字节)。", b=bars([['1000 行', a[0], f'{a[0]:.1f} ms'], ['1 万行', b[0], f'{b[0]:.1f} ms'], ['10 万行', c_[0], f'{c_[0]:.1f} ms']], c_[0], mark=[2], done=[0, 1]), t=tl(S(1)), mark=lidx(S(1), '100000'), done=lidx(S(1), '1000 ', '10000'), kv=KV([['10 万行', f'{c_[0]:.0f} ms,{c_[1] / 1e6:.1f} MB'], ['峰值内存', f'约 {c_[2] / 1e6:.0f} MB']], ['10 万行'])),
    step(f"同样 10 万行:json.dumps 默认(分隔符带空格){se['json.dumps(默认,带空格分隔)'][0]:.1f} ms、{se['json.dumps(默认,带空格分隔)'][1] / 1e6:.2f} MB;紧凑 separators {se['json.dumps(紧凑 separators)'][0]:.1f} ms、{se['json.dumps(紧凑 separators)'][1] / 1e6:.2f} MB;orjson {se['orjson.dumps'][0]:.1f} ms、{se['orjson.dumps'][1] / 1e6:.2f} MB——约 {se['json.dumps(紧凑 separators)'][0] / se['orjson.dumps'][0]:.0f} 倍快。Flask 的 jsonify 非 debug 时用紧凑格式(11.14 MB),所以响应大小和紧凑的 json.dumps 一致。", b=bars([['json.dumps', se['json.dumps(紧凑 separators)'][0], f"{se['json.dumps(紧凑 separators)'][0]:.0f} ms"], ['orjson', se['orjson.dumps'][0], f"{se['orjson.dumps'][0]:.1f} ms"]], se['json.dumps(紧凑 separators)'][0], mark=[0], done=[1]), t=tl(S(2)), done=lidx(S(2), 'orjson'), mark=lidx(S(2), 'json.dumps'), kv=KV([['标准库 json', f"{se['json.dumps(紧凑 separators)'][0]:.0f} ms"], ['orjson', f"{se['orjson.dumps'][0]:.1f} ms"]], ['orjson'])),
    step(f"debug 模式会让 JSON 带缩进:1000 行的响应,非 debug 是 {R['debug']['False'][0] / 1e3:.0f} KB,debug=True 是 {R['debug']['True'][0] / 1e3:.0f} KB。在 debug 下做性能测试会高估响应大小与序列化时间。", t=tl(S(3)), mark=lidx(S(3), 'debug=True'), done=lidx(S(3), 'debug=False'), kv=KV([['debug=False', f"{R['debug']['False'][0] / 1e3:.0f} KB"], ['debug=True', f"{R['debug']['True'][0] / 1e3:.0f} KB"]], ['debug=True'])),
    step(f"gzip 压缩:11.14 MB 的 JSON 压成 {gz['1'][1] / 1e6:.2f} MB(level 1,{gz['1'][1] / gz['1'][0] * 100:.1f}%,压缩 {gz['1'][2]:.0f} ms);level 6 {gz['6'][1] / 1e6:.2f} MB、{gz['6'][2]:.0f} ms;level 9 {gz['9'][1] / 1e6:.2f} MB、{gz['9'][2]:.0f} ms。重复结构多的 JSON 能压到约 10%,级别提高收益很小、耗时翻倍。", b=bars([['level 1', gz['1'][2], f"{gz['1'][2]:.0f} ms"], ['level 6', gz['6'][2], f"{gz['6'][2]:.0f} ms"], ['level 9', gz['9'][2], f"{gz['9'][2]:.0f} ms"]], gz['9'][2], mark=[2], done=[0]), t=tl(S(4)), done=lidx(S(4), 'level 1'), mark=lidx(S(4), 'level 9'), kv=KV([['压缩后大小', f"约 {gz['6'][1] / gz['6'][0] * 100:.0f}%"], ['level 1 → 9', '耗时约 5 倍,体积只小 3%']], ['压缩后大小'])),
    step(f"真实 gunicorn:/big(10 万行,{lv[2] / 1e6:.1f} MB)收到响应头用了 {lv[0]:.0f} ms、读完全部 {lv[1]:.0f} ms——响应头在整个 JSON 生成完之后才发出(首字节时间 = 计算时间),并带完整的 Content-Length。/slow 睡 4 秒、gunicorn --timeout 2:客户端得到 {to[0]},用时 {to[1]:.0f} ms;服务端日志是 WORKER TIMEOUT,随后新起了一个 worker。视图生成时间超过 worker timeout 会被杀掉。", t=tl(S(5)), done=lidx(S(5), '/big'), mark=lidx(S(5), '/slow', '服务端日志'), kv=KV([['首字节时间', '等于整个响应的生成时间'], ['超过 --timeout', 'worker 被杀,客户端 500']], ['首字节时间'])),
]
A = mkartf('f117', 117, 'Flask,JSON,大响应,orjson,gzip,真实验证,动画演示',
    f'实测 Flask 大批量 JSON 响应:10 万行 jsonify {c_[0]:.0f} ms、{c_[1] / 1e6:.1f} MB、峰值内存约 {c_[2] / 1e6:.0f} MB;orjson 比标准库快约 {se["json.dumps(紧凑 separators)"][0] / se["orjson.dumps"][0]:.0f} 倍;debug 模式让响应变大;gzip 压到约 10%;真实 gunicorn 里首字节时间等于生成时间,超过 worker timeout 会被杀。',
    '一次返回几十万行 JSON 会怎样?内存要多少?换成 orjson 能快多少?压缩划不划算?超过 gunicorn 超时会发生什么?这篇逐项量出来。',
    [(f'{c_[0]:.0f} ms / {c_[1] / 1e6:.0f} MB', '10 万行 jsonify 的耗时与响应大小'), (f'约 {se["json.dumps(紧凑 separators)"][0] / se["orjson.dumps"][0]:.0f} 倍', 'orjson 相对标准库 json.dumps 的速度'), ('WORKER TIMEOUT', '视图执行超过 gunicorn --timeout 时的日志')],
    [('线性增长', '<p>上一篇:<a href="flask-pydantic-in-flask.html">Pydantic 在 Flask 中的使用</a>;下一篇:<a href="flask-streaming-json.html">Streaming JSON</a>。</p>'), ('序列化方式', None), ('debug 模式', None), ('gzip 压缩', '<p>这里用 Python 的 gzip 模块测压缩比与耗时;反向代理(nginx)压缩见部署部分。</p>'), ('首字节时间与 worker timeout', None)],
    steps, [ENV_F + '。orjson 3.12.0、gunicorn sync worker', '没有验证:Flask-Compress 与 nginx gzip 的实际表现、brotli、分块传输下的客户端内存、浏览器解析大 JSON 的耗时、数据库取 10 万行本身的耗时与内存(见流式响应一篇)'], '大批量 JSON 响应', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
